window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e1744574d8081c05"]={"versions": [{"id": "FIG-e1744574d8081c05", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Werkzeugkettendiagramm (Tool Chain / Workflow) zur AUTOSAR-Systembeschreibung und zum Modellaustausch zwischen OEM und Zulieferer (Supplier) gemäß AUTOSAR TR Interoperability of AUTOSAR Tools.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Organisationsdomänen / Swimlanes</strong>:\n<ul class=\"fig-list\"><li><code>OEM</code>: Umfasst die Systemerstellung, Systemerweiterung, Extraktion und Systemkonfiguration.\n</li><li><code>Supplier</code>: Umfasst die Implementierung und Verfeinerung von Teilsystembeschreibungen.\n</li></ul>\n</li><li><strong>Werkzeuge (Tools)</strong>:\n<ul class=\"fig-list\"><li><code>Authoring Tool 1</code>: Werkzeug zur initialen Modellgenerierung bei der OEM-Domäne.\n</li><li><code>Authoring Tool 2</code>: Werkzeug zur Bearbeitung und Anreicherung der Systembeschreibung beim OEM.\n</li><li><code>Extract Tool</code>: Werkzeug zur Erzeugung lieferantenspezifischer Systemauszüge beim OEM.\n</li><li><code>Authoring Tool 3</code>: Werkzeug zur Implementierung und Verfeinerung beim Zulieferer.\n</li></ul>\n</li><li><strong>Prozessschritte (Aktivitäten)</strong>:\n<ul class=\"fig-list\"><li><code>generate AUTOSAR model from existing data</code> (OEM)\n</li><li><code>edit system description</code> (OEM)\n</li><li><code>Configure System</code> (OEM)\n</li><li><code>extract system description for supplier</code> (OEM)\n</li><li><code>implement and refine system description</code> (Supplier)\n</li></ul>\n</li><li><strong>Artefakte / Datenobjekte</strong>:\n<ul class=\"fig-list\"><li><code>existing data</code>: Nicht-AUTOSAR-Ausgangsdaten / Bestandsdaten.\n</li><li><code>initial system description : System</code>: AUTOSAR-XML-Artefakt (.XML) nach Erstgenerierung.\n</li><li><code>extended system description : System</code>: Angereichertes AUTOSAR-XML-Artefakt (.XML).\n</li><li><code>extract from OEM ssystem description : System</code>: Auszug der Systembeschreibung (.XML) für den Zulieferer.\n</li><li><code>refined system description : System</code>: Verfeinertes und zurückgeliefertes AUTOSAR-XML-Artefakt (.XML) des Zulieferers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Authoring Tool 1</code> transformiert <code>existing data</code> über die Aktivität <code>generate AUTOSAR model from existing data</code> in die <code>initial system description : System</code> (.XML).\n</li><li><code>Authoring Tool 2</code> bearbeitet und ergänzt diese Datei im Schritt <code>edit system description</code>, woraus die <code>extended system description : System</code> (.XML) resultiert.\n</li><li>Die <code>extended system description : System</code> wird im Schritt <code>extract system description for supplier</code> über das <code>Extract Tool</code> aufbereitet; daraus entsteht das Teilartefakt <code>extract from OEM ssystem description : System</code> (.XML).\n</li><li>Das extrahierte XML-Artefakt wird an den <code>Supplier</code> übergeben.\n</li><li>Der Zulieferer verarbeitet das Modell im Schritt <code>implement and refine system description</code> unter Nutzung von <code>Authoring Tool 3</code> und erstellt die <code>refined system description : System</code> (.XML).\n</li><li>Die verfeinerte Systembeschreibung wird an den OEM zurückgeführt und fließt gemeinsam mit der Systemgesamtsicht in den OEM-Schritt <code>Configure System</code> ein.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den standardisierten Roundtrip- bzw. Handover-Workflow für AUTOSAR-XML-Dateien (<code>ARXML</code>) über Organisationsgrenzen hinweg. Für die Interoperabilität ist sicherzustellen, dass Extraktionswerkzeuge (<code>Extract Tool</code>) semantisch und syntaktisch valide Teilmodelle des Typs <code>System</code> erzeugen und dass Autorentoolketten (<code>Authoring Tool 1–3</code>) konsistente XML-Schemata und Modellversionen gemäß den Spezifikationsvorgaben verwenden, um verlustfreie Modellzusammenführungen im Konfigurationsschritt zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-26c52f7214886ea2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Ablauf- und Werkzeugkettendiagramm (Tool Chain / Workflow) zur AUTOSAR-Systembeschreibung und zum Modellaustausch zwischen OEM und Zulieferer (Supplier) gemäß AUTOSAR TR Interoperability of AUTOSAR Tools.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Organisationsdomänen / Swimlanes</strong>:\n<ul class=\"fig-list\"><li><code>OEM</code>: Umfasst die Systemerstellung, Systemerweiterung, Extraktion und Systemkonfiguration.\n</li><li><code>Supplier</code>: Umfasst die Implementierung und Verfeinerung von Teilsystembeschreibungen.\n</li></ul>\n</li><li><strong>Werkzeuge (Tools)</strong>:\n<ul class=\"fig-list\"><li><code>Authoring Tool 1</code>: Werkzeug zur initialen Modellgenerierung bei der OEM-Domäne.\n</li><li><code>Authoring Tool 2</code>: Werkzeug zur Bearbeitung und Anreicherung der Systembeschreibung beim OEM.\n</li><li><code>Extract Tool</code>: Werkzeug zur Erzeugung lieferantenspezifischer Systemauszüge beim OEM.\n</li><li><code>Authoring Tool 3</code>: Werkzeug zur Implementierung und Verfeinerung beim Zulieferer.\n</li></ul>\n</li><li><strong>Prozessschritte (Aktivitäten)</strong>:\n<ul class=\"fig-list\"><li><code>generate AUTOSAR model from existing data</code> (OEM)\n</li><li><code>edit system description</code> (OEM)\n</li><li><code>Configure System</code> (OEM)\n</li><li><code>extract system description for supplier</code> (OEM)\n</li><li><code>implement and refine system description</code> (Supplier)\n</li></ul>\n</li><li><strong>Artefakte / Datenobjekte</strong>:\n<ul class=\"fig-list\"><li><code>existing data</code>: Nicht-AUTOSAR-Ausgangsdaten / Bestandsdaten.\n</li><li><code>initial system description : System</code>: AUTOSAR-XML-Artefakt (.XML) nach Erstgenerierung.\n</li><li><code>extended system description : System</code>: Angereichertes AUTOSAR-XML-Artefakt (.XML).\n</li><li><code>extract from OEM ssystem description : System</code>: Auszug der Systembeschreibung (.XML) für den Zulieferer.\n</li><li><code>refined system description : System</code>: Verfeinertes und zurückgeliefertes AUTOSAR-XML-Artefakt (.XML) des Zulieferers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><code>Authoring Tool 1</code> transformiert <code>existing data</code> über die Aktivität <code>generate AUTOSAR model from existing data</code> in die <code>initial system description : System</code> (.XML).\n</li><li><code>Authoring Tool 2</code> bearbeitet und ergänzt diese Datei im Schritt <code>edit system description</code>, woraus die <code>extended system description : System</code> (.XML) resultiert.\n</li><li>Die <code>extended system description : System</code> wird im Schritt <code>extract system description for supplier</code> über das <code>Extract Tool</code> aufbereitet; daraus entsteht das Teilartefakt <code>extract from OEM ssystem description : System</code> (.XML).\n</li><li>Das extrahierte XML-Artefakt wird an den <code>Supplier</code> übergeben.\n</li><li>Der Zulieferer verarbeitet das Modell im Schritt <code>implement and refine system description</code> unter Nutzung von <code>Authoring Tool 3</code> und erstellt die <code>refined system description : System</code> (.XML).\n</li><li>Die verfeinerte Systembeschreibung wird an den OEM zurückgeführt und fließt gemeinsam mit der Systemgesamtsicht in den OEM-Schritt <code>Configure System</code> ein.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den standardisierten Roundtrip- bzw. Handover-Workflow für AUTOSAR-XML-Dateien (<code>ARXML</code>) über Organisationsgrenzen hinweg. Für die Interoperabilität ist sicherzustellen, dass Extraktionswerkzeuge (<code>Extract Tool</code>) semantisch und syntaktisch valide Teilmodelle des Typs <code>System</code> erzeugen und dass Autorentoolketten (<code>Authoring Tool 1–3</code>) konsistente XML-Schemata und Modellversionen gemäß den Spezifikationsvorgaben verwenden, um verlustfreie Modellzusammenführungen im Konfigurationsschritt zu gewährleisten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e1744574d8081c05", "to": "FIG-26c52f7214886ea2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
